// ===== Mệnh Quái (Đông Tứ Mệnh / Tây Tứ Mệnh) từ năm sinh Dương lịch + giới tính =====
// Công thức chuẩn phổ biến trong Bát Trạch — CẦN KA XÁC NHẬN LẠI vì đây là công thức tiêu chuẩn
// tôi áp dụng, không phải nguyên văn Ka cung cấp.
window.tinhMenhQuai = function (namSinh, gioiTinh) {
    let hai_so_cuoi = namSinh % 100;
    let tong = Math.floor(hai_so_cuoi / 10) + (hai_so_cuoi % 10);
    while (tong > 9) tong = Math.floor(tong / 10) + (tong % 10);
    let quaiSo;
    let sauNam2000 = namSinh >= 2000;
    if (gioiTinh === "nam") {
        quaiSo = sauNam2000 ? (9 - tong) : (10 - tong);
        while (quaiSo <= 0) quaiSo += 9;
        while (quaiSo > 9) quaiSo -= 9;
        if (quaiSo === 5) quaiSo = 2; // Nam Ngũ Hoàng ký Khôn
    } else {
        quaiSo = sauNam2000 ? (6 + tong) : (5 + tong);
        while (quaiSo > 9) quaiSo -= 9;
        if (quaiSo === 5) quaiSo = 8; // Nữ Ngũ Hoàng ký Cấn
    }
    const CUNG_THEO_QUAI = { 1: "Khảm", 2: "Khôn", 3: "Chấn", 4: "Tốn", 6: "Càn", 7: "Đoài", 8: "Cấn", 9: "Ly" };
    const DONG_TAY = { "Khảm": "Đông Tứ Mệnh", "Chấn": "Đông Tứ Mệnh", "Tốn": "Đông Tứ Mệnh", "Ly": "Đông Tứ Mệnh",
                        "Khôn": "Tây Tứ Mệnh", "Càn": "Tây Tứ Mệnh", "Đoài": "Tây Tứ Mệnh", "Cấn": "Tây Tứ Mệnh" };
    let cung = CUNG_THEO_QUAI[quaiSo];
    return { quaiSo, cung, hanh: window.HANH_CUA_CUNG[cung], nhom: DONG_TAY[cung] };
};
